        "focus": "วัสดุสแตติกที่สลายพลังงานตามABS ใช้เทคโนโลยีเสริมคาร์บอนไฟเบอร์แนวทางการใช้งานรวมถึงแหนบ ตัวเรือนโทรศัพท์และกล้อง ตัวเครื่องใช้ไฟฟ้า ถาดชิป ชิ้นส่วนอิเล็กทรอนิกส์ แผ่นบรรจุภัณฑ์ และชิ้นส่วนอิเล็กทรอนิกส์;ตรวจสอบความทนทานและสภาพการผลิตสําหรับเกรดและชิ้นส่วนสําเร็จรูป",
        "process": "ยืนยันการอบแห้ง อุณหภูมิหลอมละลาย อุณหภูมิแม่พิมพ์ และระยะเวลาการอยู่อาศัยของเกรด;ตรวจสอบความต้านทาน รูปลักษณ์ และขนาดหลังจากการทดสอบ",
