        "focus": "วัสดุนําไฟฟ้าที่ผลิตจากPC ใช้เทคโนโลยีคาร์บอนดําดัดแปลงพร้อมทิศทางการปรุงสูตรหน่วงไฟแนวทางการใช้งานรวมถึงแผ่นไม้ แผ่นเทปพาหะ โปรไฟล์ แหนบ ชิ้นส่วนอิเล็กทรอนิกส์ ตัวเรือนไฟฟ้า ภาชนะ และอุปกรณ์สื่อสาร;ตรวจสอบความทนทานและสภาพการแปรรูปสําหรับเกรดและชิ้นส่วนสําเร็จรูป",
