        "focus": "วัสดุสแตติกที่ผลิตจากPC ใช้เทคโนโลยีคาร์บอนแบล็คดัดแปลงแนวทางการใช้งานรวมถึงแผ่นไม้ แผ่นเทปพาหะ โปรไฟล์ แหนบ ชิ้นส่วนอิเล็กทรอนิกส์ ตัวเรือน ภาชนะ และอุปกรณ์สื่อสาร;ตรวจสอบความทนทานและสภาพการแปรรูปสําหรับเกรดและชิ้นส่วนสําเร็จรูป",
